head.b:skin:
/* ---------------------------------------------------------------------------------------
SUSHI ELITE v86.1 [HOTFIX]
---------------------------------------------------------------------------------------
*/
    :root {
        --primary: #ce1212; --primary-dark: #a00d0d;
        --secondary: #37373f; --accent: #ffc107;
        --bg-body: #f8f9fa; --bg-card: #ffffff;
        --text-main: #1d1d1f; --text-muted: #86868b;
        --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
        --transition: 0.3s cubic-bezier(0.165, 0.84, 0.44, 1);
        --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
        --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);
        --radius-xl: 24px;
        --z-marquee: 1040; --z-navbar: 1030; --z-sticky: 1020; --z-toast: 1060; --z-bottom-bar: 1050;
    }

    [data-theme='dark'] { 
        --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
        --text-main: #f5f5f7; --text-muted: #a1a1a6;
    }

    body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 115px; padding-bottom: 95px; overflow-x: hidden; -webkit-tap-highlight-color: transparent; }

    /* [MARQUEE ANNOUNCEMENT] */
    .marquee-bar { position: fixed; top: 0; left: 0; width: 100%; height: 30px; background: #000; color: #fff; z-index: var(--z-marquee); overflow: hidden; display: flex; align-items: center; font-size: 0.8rem; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; }
    .marquee-content { display: inline-block; white-space: nowrap; animation: marquee 20s linear infinite; padding-left: 100%; }
    @keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }

    .header { background: var(--bg-card); height: 85px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); top: 30px; }
    .card, .product-card, .glass-panel { background: var(--bg-card) !important; border: 1px solid rgba(0,0,0,0.05); }

    h1, .display-1 { font-size: clamp(2.2rem, 6vw, 4rem); font-weight: 800; letter-spacing: -1.5px; }
    h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.2rem); font-weight: 700; }
    .lead { font-size: clamp(0.95rem, 2vw, 1.15rem); line-height: 1.6; }

    #scroll-fill { position: fixed; top: 30px; left: 0; height: 4px; background: var(--primary); z-index: 9999; width: 0%; transition: width 0.1s; }
    #scroll-sentinel { height: 100px; width: 100%; display: flex; justify-content: center; align-items: center; }

    .sticky-tools { position: sticky; top: 115px; z-index: var(--z-sticky); background: var(--bg-body); padding-top: 15px; padding-bottom: 10px; border-bottom: 1px solid rgba(0,0,0,0.05); transition: background 0.3s; }
    [data-theme='dark'] .sticky-tools { background: var(--bg-body); }

    .search-input { width: 100%; border-radius: 50px; border: 1px solid rgba(0,0,0,0.1); padding: 12px 50px 12px 20px; background: var(--bg-card); color: var(--text-main); transition: 0.3s; box-shadow: var(--shadow-sm); }
    .search-input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(206,18,18,0.1); }
    .search-icon { position: absolute; right: 20px; top: 50%; transform: translateY(-50%); color: var(--text-muted); font-size: 1.1rem; pointer-events: none; }

    .filter-scroll { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 5px; scrollbar-width: none; }
    .filter-scroll::-webkit-scrollbar { display: none; }
    .filter-chip { white-space: nowrap; padding: 8px 20px; border-radius: 50px; background: var(--bg-card); border: 1px solid rgba(0,0,0,0.1); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.3s; }
    .filter-chip:hover, .filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }

    .product-card { border-radius: var(--radius-xl); overflow: hidden; height: 100%; transition: var(--transition); position: relative; }
    .product-card:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); }
    .product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #f0f0f0; cursor: pointer; }
    .product-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease, opacity 0.3s; }
    .product-card:hover .product-img { transform: scale(1.1); }

    .wish-btn { position: absolute; top: 15px; right: 15px; z-index: 10; background: #fff; border: none; border-radius: 50%; width: 40px; height: 40px; color: #ccc; box-shadow: 0 4px 10px rgba(0,0,0,0.1); transition: 0.3s; }
    .wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }

    /* [BADGES] */
    .stock-badge { position: absolute; top: 15px; left: 15px; z-index: 10; padding: 4px 10px; border-radius: 4px; font-size: 0.75rem; font-weight: bold; color: #fff; text-transform: uppercase; }
    .stock-low { background: #e67e22; animation: pulse 2s infinite; }
    .stock-out { background: #c0392b; }

    .hot-badge { position: absolute; top: 15px; left: 15px; z-index: 10; background: linear-gradient(45deg, #ff0000, #ff8800); color: #fff; padding: 4px 10px; border-radius: 4px; font-weight: 800; font-size: 0.8rem; box-shadow: 0 4px 10px rgba(255,0,0,0.4); }
    .discount-badge { position: absolute; top: 45px; left: 15px; z-index: 9; background: #000; color: #fff; padding: 2px 6px; border-radius: 4px; font-weight: 700; font-size: 0.7rem; }
    .old-price { text-decoration: line-through; color: #999; font-size: 0.9rem; margin-right: 5px; }

    @keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.6; } 100% { opacity: 1; } }

    .toast-container { bottom: 90px; right: 20px; top: auto !important; z-index: var(--z-toast); }
    .glass-toast { background: rgba(30, 30, 30, 0.85) !important; backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); color: #fff; border-radius: 16px; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 10px 30px rgba(0,0,0,0.3); margin-bottom: 10px; }
    .glass-toast .btn-close { filter: invert(1); }

    .hero-slide { height: 350px; object-fit: cover; border-radius: 24px; filter: brightness(0.8); }
    .carousel-caption { bottom: 40px; text-shadow: 0 2px 10px rgba(0,0,0,0.5); }

    .fly-img { position: fixed; z-index: 10000; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; width: 100px; height: 100px; object-fit: cover; box-shadow: 0 10px 30px rgba(0,0,0,0.3); pointer-events: none; }
    .skeleton { background: linear-gradient(to right, #eeeeee 8%, #dddddd 18%, #eeeeee 33%); background-size: 1000px 100%; animation: shimmer 1.5s infinite linear; }
    @keyframes shimmer { 0% { background-position: -1000px 0; } 100% { background-position: 1000px 0; } }
    .module-section { display: none !important; opacity: 0; animation: fadeIn 0.4s forwards; }
    .module-section.active { display: block !important; opacity: 1; }
    @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

    .swatch-item { padding: 8px 16px; border-radius: 8px; cursor: pointer; border: 2px solid transparent; background: #eee; font-size: 0.9rem; font-weight: 600; color: #555; transition: 0.2s; margin-right:8px; margin-bottom:8px; display:inline-block; }
    .swatch-item.active { border-color: var(--primary); background: var(--primary); color: #fff; }
    .btn-trash { border: none; background: transparent; color: #999; transition: 0.2s; }
    .btn-trash:hover { color: var(--primary); transform: scale(1.2); }

    .mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 80px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: 1050; border-top: 1px solid rgba(0,0,0,0.1); }
    .mobile-toolbar a { color: var(--text-main); font-size: 1.5rem; }

    .btn-scroll-top { position: fixed; bottom: 100px; right: 20px; width: 50px; height: 50px; border-radius: 50%; background: var(--primary); color: #fff; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; box-shadow: 0 10px 20px rgba(0,0,0,0.2); z-index: 1040; opacity: 0; pointer-events: none; transition: 0.3s; border:none; }
    .btn-scroll-top.visible { opacity: 1; pointer-events: all; }

    .captcha-box { background: #f8f9fa; border: 1px solid #eee; border-radius: 12px; padding: 15px; display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 20px; }
    .captcha-question { font-weight: 800; font-size: 1.2rem; letter-spacing: 1px; color: var(--primary); }
    .captcha-input { width: 80px; text-align: center; font-weight: bold; border-radius: 8px; border: 2px solid #eee; }
    .captcha-input:focus { border-color: var(--primary); outline: none; }
    .is-invalid { border-color: #dc3545 !important; animation: shake 0.3s; }
    @keyframes shake { 0% { transform: translateX(0); } 25% { transform: translateX(-5px); } 50% { transform: translateX(5px); } 75% { transform: translateX(-5px); } 100% { transform: translateX(0); } }
    @keyframes bump { 0% { transform: scale(1); } 50% { transform: scale(1.4); } 100% { transform: scale(1); } }
    .bump-anim { animation: bump 0.3s ease; }

    .bottom-cart-bar { position: fixed; bottom: 0; left: 0; width: 100%; background: var(--text-main); color: #fff; padding: 15px 20px; z-index: var(--z-bottom-bar); display: flex; justify-content: space-between; align-items: center; box-shadow: 0 -5px 20px rgba(0,0,0,0.2); transform: translateY(100%); transition: transform 0.3s ease; padding-bottom: max(15px, env(safe-area-inset-bottom)); }
    .bottom-cart-bar.active { transform: translateY(0); }
    .bottom-cart-bar.has-nav { bottom: 80px; } 
    .btn-view-cart { background: #fff; color: var(--text-main); font-weight: 800; border-radius: 50px; padding: 8px 20px; text-decoration: none; display:flex; align-items:center; gap:8px; }

    .card-qty-ctrl { display: flex; align-items: center; background: var(--primary); border-radius: 50px; overflow: hidden; height: 38px; width: 100%; }
    .card-qty-btn { border: none; background: transparent; color: #fff; width: 30%; height: 100%; font-weight: 800; font-size: 1.2rem; }
    .card-qty-val { color: #fff; font-weight: 800; width: 40%; text-align: center; }

    .extras-list .form-check-input:checked { background-color: var(--primary); border-color: var(--primary); }
    .order-type-switch .btn-check:checked + .btn { background-color: var(--text-main); color: #fff; border-color: var(--text-main); }

    /* [COUPON UI] */
    .coupon-box { display: flex; gap: 10px; margin-bottom: 20px; }
    .coupon-input { text-transform: uppercase; font-weight: bold; border-style: dashed; }

    /* [SERVICE BANNER] */
    .service-banner { font-size: 0.75rem; white-space: nowrap; overflow-x: auto; padding: 8px 0; background: #f8f9fa; border-bottom: 1px solid rgba(0,0,0,0.05); }
    .service-banner::-webkit-scrollbar { display: none; }
    .service-item { display: inline-flex; align-items: center; gap: 5px; margin-right: 20px; color: var(--text-muted); font-weight: 500; }
    .service-item i { color: var(--primary); }

body.script:
//
/**
 * SUSHI ELITE MONOLITH v86.1 (Hotfix)
 */

const ERROR_IMG = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1 1'%3E%3Crect width='1' height='1' fill='%23cccccc'/%3E%3C/svg%3E";
const PLACEHOLDER_IMG = "https://placehold.co/600x400/ce1212/ffffff?text=Sushi+Elite";

const DELIVERY_THRESHOLD = 150; 
const DELIVERY_COST = 15;

// COUPON CONFIG
const COUPONS = {
    'SUSHI10': { type: 'percent', val: 0.10 },
    'FREESHIP': { type: 'free_ship', val: 0 }
};

const App = {
    State: {
        catalog: [], filteredCatalog: [], cart: [], wishlist: [], history: [],
        currency: 'DH', renderCount: 0, batchSize: 20, activeCategory: 'All', searchQuery: '',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        qvProduct: null, qvQty: 1, qvMultiplier: 1.0,
        captchaAnswer: 0, orderType: 'delivery',
        qvExtras: [], discount: 0, activeCoupon: ''
    },

    Utils: {
        safeStr: (str) => str ? str.replace(/['"`]/g, '') : '',
        formatPrice: (val) => {
            if(!val && val !== 0) return "0.00 " + App.State.currency;
            const r = Number(val) * App.State.rates[App.State.currency];
            return `${r.toFixed(2)} ${App.State.currency}`;
        },
        generateId: () => Math.random().toString(36).substr(2, 9),
        checkStatus: () => {
            const hour = new Date().getHours();
            const isOpen = hour >= 9 || hour < 6;
            const html = isOpen 
                ? `<i class="bi bi-circle-fill text-success" style="font-size:8px; vertical-align:middle"></i> Open Now`
                : `<i class="bi bi-circle-fill text-danger" style="font-size:8px; vertical-align:middle"></i> Closed (Opens 9AM)`;
            document.getElementById('store-status').innerHTML = html;
            const mob = document.getElementById('store-status-mobile');
            if(mob) mob.innerHTML = `<span class='badge bg-light text-dark border'>${html}</span>`;
        },
        getEmoji: (cat) => {
            const c = cat.toLowerCase();
            if(c.includes('sushi')) return '🍣';
            if(c.includes('soup') || c.includes('ramen')) return '🍜';
            if(c.includes('drink') || c.includes('juice')) return '🥤';
            if(c.includes('dessert') || c.includes('cake')) return '🍰';
            return '🍽️';
        },
        debounce: (func, wait) => {
            let timeout;
            return function(...args) {
                clearTimeout(timeout);
                timeout = setTimeout(() => func.apply(this, args), wait);
            };
        },
        initCaptcha: () => {
            const n1 = Math.floor(Math.random() * 9) + 1;
            const n2 = Math.floor(Math.random() * 9) + 1;
            App.State.captchaAnswer = n1 + n2;
            const el = document.getElementById('captcha-question');
            if(el) el.innerText = `${n1} + ${n2} = ?`;
            const input = document.getElementById('captcha-input');
            if(input) input.value = '';
        },
        // HOTFIX: Restore Countdown
        startCountdown: () => {
            let time = 20 * 60; // 20 minutes
            const el = document.getElementById('countdown-timer');
            if(!el) return;
            setInterval(() => {
                const m = Math.floor(time / 60);
                const s = time % 60;
                el.innerText = `${m < 10 ? '0'+m : m}:${s < 10 ? '0'+s : s}`;
                if(time > 0) time--;
            }, 1000);
        },
        animateValue: (obj, start, end, duration) => {
            let startTimestamp = null;
            const step = (timestamp) => {
                if (!startTimestamp) startTimestamp = timestamp;
                const progress = Math.min((timestamp - startTimestamp) / duration, 1);
                obj.innerHTML = App.Utils.formatPrice(Math.floor(progress * (end - start) + start));
                if (progress < 1) {
                    window.requestAnimationFrame(step);
                } else {
                    obj.innerHTML = App.Utils.formatPrice(end);
                }
            };
            window.requestAnimationFrame(step);
        }
    },

    UI: {
        toast: (msg, type='light') => {
            const c = document.getElementById('toast-container');
            const el = document.createElement('div');
            const icon = type === 'success' ? 'check-circle-fill text-success' : (type === 'danger' ? 'exclamation-circle-fill text-danger' : 'info-circle-fill text-info');
            el.className = `toast glass-toast show fade`;
            el.innerHTML = `<div class="d-flex align-items-center p-3"><i class="bi bi-${icon} fs-4 me-3"></i><div class="fw-bold">${msg}</div><button type="button" class="btn-close ms-auto me-2" data-bs-dismiss="toast"></button></div>`;
            c.appendChild(el);
            setTimeout(() => { el.classList.remove('show'); setTimeout(() => el.remove(), 300); }, 3500);
        },

        confirm: (title, msg, onConfirm) => {
            document.getElementById('conf-title').innerText = title;
            document.getElementById('conf-msg').innerText = msg;
            const btn = document.getElementById('conf-yes');
            const newBtn = btn.cloneNode(true);
            btn.parentNode.replaceChild(newBtn, btn);
            newBtn.addEventListener('click', () => {
                onConfirm();
                bootstrap.Modal.getInstance(document.getElementById('confirmModal')).hide();
            });
            new bootstrap.Modal(document.getElementById('confirmModal')).show();
        },

        flyToCart: (img) => {
            if(!img || !img.src) return;
            const cart = document.getElementById('nav-cart-wrapper');
            if(!cart) return;
            const clone = img.cloneNode();
            const rect = img.getBoundingClientRect();
            const tRect = cart.getBoundingClientRect();
            clone.classList.add('fly-img');
            clone.style.top = `${rect.top}px`;
            clone.style.left = `${rect.left}px`;
            clone.style.width = `${rect.width}px`;
            clone.style.height = `${rect.height}px`;
            document.body.appendChild(clone);
            requestAnimationFrame(() => {
                clone.style.top = `${tRect.top}px`;
                clone.style.left = `${tRect.left}px`;
                clone.style.width = '20px';
                clone.style.height = '20px';
                clone.style.opacity = '0';
            });
            setTimeout(() => {
                clone.remove();
                cart.classList.add('bump-anim');
                setTimeout(() => cart.classList.remove('bump-anim'), 300);
            }, 800);
        },

        updateBadge: () => {
            const total = App.State.cart.reduce((a, b) => a + b.qty, 0);
            document.getElementById('cart-count').innerText = total;
            const bar = document.getElementById('bottom-cart-bar');
            if(bar) {
                if(total > 0) {
                    bar.classList.add('active');
                    if(window.innerWidth < 992) bar.classList.add('has-nav');
                    document.getElementById('bar-count').innerText = total;
                    const totalAmount = App.State.cart.reduce((sum, item) => sum + (item.finalPrice * item.qty), 0);
                    document.getElementById('bar-total').innerText = App.Utils.formatPrice(totalAmount);
                } else {
                    bar.classList.remove('active');
                }
            }
        }
    },

    Catalog: {
        init: () => {
            App.State.observer = new IntersectionObserver((entries) => {
                if(entries[0].isIntersecting) {
                    App.Catalog.renderBatch();
                }
            }, { rootMargin: '100px' });
        },

        processTags: (tags) => {
            const meta = { tags: tags, price: 50, stock: 99, cat: 'Uncategorized', altImg: null, sku: App.Utils.generateId(), oldPrice: null, isHot: false };
            tags.forEach(t => {
                if(t.startsWith('price-')) meta.price = parseFloat(t.split('-')[1]);
                if(t.startsWith('old-')) meta.oldPrice = parseFloat(t.split('-')[1]);
                if(t.startsWith('stock-')) meta.stock = parseInt(t.split('-')[1]);
                if(t.startsWith('cat-')) meta.cat = t.replace('cat-', '');
                if(t.startsWith('img-alt-url')) meta.altImg = t.replace('img-alt-url-', 'https'); 
                if(t.startsWith('sku-')) meta.sku = t.split('-')[1];
                if(t === 'hot') meta.isHot = true;
            });
            if(meta.sku.includes('F')) meta.isHot = Math.random() > 0.7; 
            return meta;
        },

        renderBatch: () => {
            const { filteredCatalog, renderCount, batchSize } = App.State;
            const container = document.getElementById('product-grid-root');
            const sentinel = document.getElementById('scroll-sentinel');
            const loader = document.getElementById('loader-sentinel');

            if (renderCount >= filteredCatalog.length) {
                if(loader) loader.classList.add('hidden');
                return;
            }

            if(loader) loader.classList.remove('hidden');

            const nextBatch = filteredCatalog.slice(renderCount, renderCount + batchSize);

            nextBatch.forEach(item => {
                container.appendChild(App.Catalog.createCard(item));
            });

            App.State.renderCount += nextBatch.length;

            if (App.State.renderCount < filteredCatalog.length) {
                App.State.observer.observe(sentinel);
            } else {
                if(loader) loader.classList.add('hidden');
            }
        },

        resetGrid: () => {
            document.getElementById('product-grid-root').innerHTML = '';
            App.State.renderCount = 0;
            App.Catalog.renderBatch();
        },

        search: (query) => {
            if(!App.Catalog._debouncedSearch) {
                App.Catalog._debouncedSearch = App.Utils.debounce((q) => {
                    App.State.searchQuery = q.toLowerCase();
                    App.Catalog.applyFilters();
                }, 300);
            }
            App.Catalog._debouncedSearch(query);
        },

        filter: (cat) => {
            App.State.activeCategory = cat;
            document.querySelectorAll('.filter-chip').forEach(el => {
                el.classList.toggle('active', el.innerText.includes(cat));
            });
            App.Catalog.applyFilters();
            const grid = document.getElementById('catalog-module');
            if(grid) {
                const y = grid.getBoundingClientRect().top + window.pageYOffset - 180;
                window.scrollTo({top: y, behavior: 'smooth'});
            }
        },

        applyFilters: () => {
            const { activeCategory, searchQuery, catalog } = App.State;
            let results = catalog;
            if(activeCategory !== 'All') results = results.filter(i => i.cat === activeCategory);
            if(searchQuery.length > 0) results = results.filter(i => i.title.toLowerCase().includes(searchQuery) || i.cat.toLowerCase().includes(searchQuery));
            App.State.filteredCatalog = results;
            App.Catalog.resetGrid();
        },

        createCard: (item) => {
            if (!item || typeof item.id === 'undefined') return document.createElement('div'); 
            const col = document.createElement('div');
            col.className = 'col-lg-4 col-md-6 col-12';

            const safeImg = item.img || PLACEHOLDER_IMG;
            const isOut = item.stock === 0;
            const isLow = item.stock < 5 && !isOut;

            let badge = '';
            if(isOut) badge = `<div class="stock-badge stock-out">Sold Out</div>`;
            else if(isLow) badge = `<div class="stock-badge stock-low">Low Stock</div>`;
            else if(item.isHot) badge = `<div class="hot-badge">🔥 HOT</div>`;
            else if(item.oldPrice && item.oldPrice > item.price) {
                const off = Math.round(((item.oldPrice - item.price) / item.oldPrice) * 100);
                badge = `<div class="discount-badge">SAVE ${off}%</div>`;
            }

            const safeId = String(item.id).replace(/'/g, "\\'");
            const isFav = App.State.wishlist.some(w => String(w.id) === String(item.id));
            const heartClass = isFav ? 'active' : '';

            const cartItem = App.State.cart.find(c => String(c.id) === String(item.id));
            let actionBtn = '';

            if(cartItem && !isOut) {
                actionBtn = `
                    <div class="card-qty-ctrl">
                        <button class="card-qty-btn" onclick="App.Cart.updateFromGrid('${safeId}', -1)">-</button>
                        <span class="card-qty-val">${cartItem.qty}</span>
                        <button class="card-qty-btn" onclick="App.Cart.updateFromGrid('${safeId}', 1)">+</button>
                    </div>
                `;
            } else {
                const btnState = isOut ? 'disabled="disabled"' : '';
                const btnText = isOut ? 'Out of Stock' : 'Add <i class="bi bi-plus"></i>';
                actionBtn = `
                    <button class="btn btn-sm btn-outline-danger rounded-pill w-100" 
                        ${btnState} 
                        onclick="App.Cart.addDirect('${safeId}', this)">
                        ${btnText}
                    </button>
                `;
            }

            const priceHtml = item.oldPrice && item.oldPrice > item.price 
                ? `<span class="old-price">${App.Utils.formatPrice(item.oldPrice)}</span> <span class="fw-bold text-danger fs-5 text-nowrap">${App.Utils.formatPrice(item.price)}</span>`
                : `<span class="fw-bold text-danger fs-5 text-nowrap">${App.Utils.formatPrice(item.price)}</span>`;

            col.innerHTML = `
                <div class="product-card shadow-sm">
                    ${badge}
                    <button class="wish-btn ${heartClass}" onclick="App.Wishlist.toggle('${safeId}')"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.QuickView.open('${safeId}')">
                        <img src="${safeImg}" class="product-img" loading="lazy" onerror="this.onerror=null;this.src='${ERROR_IMG}'"/>
                    </div>
                    <div class="p-4">
                        <h5 class="fw-bold text-truncate">${item.title}</h5>
                        <div class="d-flex justify-content-between align-items-center mt-3 gap-2">
                            <div>${priceHtml}</div>
                            <div class="flex-grow-1" style="max-width: 140px">
                                ${actionBtn}
                            </div>
                        </div>
                    </div>
                </div>
            `;
            return col;
        }
    },

    QuickView: {
        open: (id) => {
            const item = App.State.catalog.find(i => String(i.id) === String(id));
            if(!item) return;

            App.State.qvProduct = item;
            App.State.qvQty = 1;
            App.State.qvMultiplier = 1.0;
            App.State.qvExtras = []; 

            const safeImg = item.img || PLACEHOLDER_IMG;
            const modalBody = document.getElementById('quickview-content');
            modalBody.innerHTML = `
                <div class="row g-0">
                    <div class="col-md-6">
                        <img src="${safeImg}" class="w-100 h-100" style="object-fit:cover; min-height:300px;" onerror="this.src='${ERROR_IMG}'"/>
                    </div>
                    <div class="col-md-6 p-4 d-flex flex-column justify-content-center">
                        <h2 class="fw-bold">${item.title}</h2>
                        <h3 class="text-danger fw-bold my-3" id="qv-price-display">${App.Utils.formatPrice(item.price)}</h3>

                        <p class="small text-muted fw-bold text-uppercase">Size</p>
                        <div class="mb-4 variant-radio-group">
                            <input type="radio" class="btn-check" name="qv_size" id="size1" autocomplete="off" checked="checked" onclick="App.QuickView.setMult(1.0)"/>
                            <label class="btn btn-outline-danger me-2 mb-2" for="size1">Regular</label>

                            <input type="radio" class="btn-check" name="qv_size" id="size2" autocomplete="off" onclick="App.QuickView.setMult(1.2)"/>
                            <label class="btn btn-outline-danger me-2 mb-2" for="size2">Box (1.2x)</label>

                            <input type="radio" class="btn-check" name="qv_size" id="size3" autocomplete="off" onclick="App.QuickView.setMult(1.5)"/>
                            <label class="btn btn-outline-danger me-2 mb-2" for="size3">Party (1.5x)</label>
                        </div>

                        <p class="small text-muted fw-bold text-uppercase">Extras</p>
                        <div class="mb-4 extras-list">
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="ex-ginger" onchange="App.QuickView.toggleExtra('Ginger', 0)"/>
                                <label class="form-check-label" for="ex-ginger">Ginger (Free)</label>
                            </div>
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="ex-wasabi" onchange="App.QuickView.toggleExtra('Wasabi', 0)"/>
                                <label class="form-check-label" for="ex-wasabi">Wasabi (Free)</label>
                            </div>
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="ex-sweet" onchange="App.QuickView.toggleExtra('Sweet Sauce', 2)"/>
                                <label class="form-check-label" for="ex-sweet">Sweet Sauce (+2 DH)</label>
                            </div>
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="ex-salty" onchange="App.QuickView.toggleExtra('Salty Sauce', 2)"/>
                                <label class="form-check-label" for="ex-salty">Salty Sauce (+2 DH)</label>
                            </div>
                        </div>

                        <div class="d-flex gap-3 mb-4">
                            <input type="number" class="form-control" value="1" min="1" style="width:70px" onchange="App.State.qvQty = parseInt(this.value)"/>
                            <button class="btn btn-danger flex-grow-1 rounded-pill fw-bold" onclick="App.QuickView.addToCart()">Add to Order</button>
                        </div>
                    </div>
                </div>
            `;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        setMult: (m) => {
            App.State.qvMultiplier = m;
            const base = App.State.qvProduct.price;
            document.getElementById('qv-price-display').innerText = App.Utils.formatPrice(base * m);
        },

        toggleExtra: (name, price) => {
            const idx = App.State.qvExtras.findIndex(e => e.name === name);
            if(idx > -1) {
                App.State.qvExtras.splice(idx, 1);
            } else {
                App.State.qvExtras.push({name, price});
            }
        },

        addToCart: () => {
            const p = App.State.qvProduct;
            const extraCost = App.State.qvExtras.reduce((sum, e) => sum + e.price, 0);
            const finalPrice = (p.price * App.State.qvMultiplier) + extraCost;

            App.Cart.pushItem({
                id: p.id,
                title: p.title,
                img: p.img,
                basePrice: p.price,
                finalPrice: finalPrice,
                qty: App.State.qvQty,
                multiplier: App.State.qvMultiplier,
                extras: [...App.State.qvExtras]
            });
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide();
            App.UI.toast('Added to cart', 'success');
            App.Catalog.resetGrid();
        }
    },

    Cart: {
        setOrderType: (type) => {
            App.State.orderType = type;
            App.Cart.render(); 
        },

        addDirect: (id, btn) => {
            const p = App.State.catalog.find(i => String(i.id) === String(id));
            if (!p) return App.UI.toast('Error adding item.', 'danger');
            App.Cart.pushItem({
                id: p.id, title: p.title, img: p.img,
                basePrice: p.price, finalPrice: p.price,
                qty: 1, multiplier: 1.0, extras: []
            });
            // Find image for animation
            const img = btn.closest('.product-card').querySelector('img');
            App.UI.flyToCart(img);
            App.UI.toast('Added to cart', 'success');
            App.Catalog.resetGrid();
        },

        // Grid Updater
        updateFromGrid: (id, delta) => {
            const idx = App.State.cart.findIndex(i => String(i.id) === String(id));
            if(idx > -1) {
                App.State.cart[idx].qty += delta;
                if(App.State.cart[idx].qty <= 0) {
                    App.State.cart.splice(idx, 1);
                    App.UI.toast('Item removed', 'light');
                }
                App.Cart.save();
                App.UI.updateBadge();
                App.Catalog.resetGrid(); 
            }
        },

        // Apply Coupon
        applyCoupon: () => {
            const code = document.getElementById('coupon-code').value.toUpperCase();
            const msg = document.getElementById('coupon-msg');
            const coup = COUPONS[code];

            if(coup) {
                App.State.activeCoupon = code;
                App.State.discount = coup;
                msg.innerHTML = `<span class="text-success"><i class="bi bi-check-circle"></i> Applied!</span>`;
                App.Cart.render();
            } else {
                App.State.activeCoupon = '';
                App.State.discount = 0;
                msg.innerHTML = `<span class="text-danger"><i class="bi bi-x-circle"></i> Invalid Code</span>`;
                App.Cart.render();
            }
        },

        pushItem: (newItem) => {
            const exist = App.State.cart.find(i => String(i.id) === String(newItem.id) && i.multiplier === newItem.multiplier && JSON.stringify(i.extras) === JSON.stringify(newItem.extras));
            if(exist) { exist.qty += newItem.qty; } else { App.State.cart.push(newItem); }
            App.Cart.save();
            App.UI.updateBadge();
        },

        remove: (idx) => {
            App.State.cart.splice(idx, 1);
            App.Cart.save();
            App.Cart.render();
            App.UI.updateBadge();
            App.Catalog.resetGrid(); 
        },

        clearAll: () => {
            if(App.State.cart.length === 0) return;
            App.UI.confirm('Empty Cart', 'Are you sure you want to remove all items?', () => {
                App.State.cart = [];
                App.Cart.save();
                App.Cart.render();
                App.UI.updateBadge();
                App.Catalog.resetGrid();
            });
        },

        save: () => localStorage.setItem('se_cart', JSON.stringify(App.State.cart)),

        render: () => {
            const list = document.getElementById('cart-items-list');
            const checkoutArea = document.getElementById('checkout-form-area');
            const progressBar = document.getElementById('delivery-progress-container');

            App.Utils.initCaptcha();

            if(App.State.cart.length === 0) {
                list.innerHTML = `
                    <div class="text-center py-5">
                        <i class="bi bi-basket3 text-muted" style="font-size: 4rem;"></i>
                        <h5 class="mt-3 text-muted">Your cart is empty</h5>
                        <button class="btn btn-outline-danger mt-3 rounded-pill px-4" onclick="window.location.hash='#catalog'">Start Shopping</button>
                    </div>
                `;
                checkoutArea.classList.add('d-none');
                progressBar.classList.add('d-none');
                document.getElementById('cart-total-display').innerText = App.Utils.formatPrice(0);
                return;
            }

            checkoutArea.classList.remove('d-none');

            if(App.State.orderType === 'delivery') {
                progressBar.classList.remove('d-none');
                document.getElementById('address-field-group').style.display = 'block';
            } else {
                progressBar.classList.add('d-none');
                document.getElementById('address-field-group').style.display = 'none';
            }

            let subtotal = 0;
            list.innerHTML = App.State.cart.map((item, idx) => {
                const lineTotal = item.finalPrice * item.qty;
                subtotal += lineTotal;
                const variantLabel = item.multiplier === 1.2 ? 'Box' : (item.multiplier === 1.5 ? 'Party' : 'Regular');
                const safeExtras = item.extras || [];
                const exLabel = safeExtras.length ? `<div class="small text-muted">+ ${safeExtras.map(e => e.name).join(', ')}</div>` : '';
                const safeImg = item.img || PLACEHOLDER_IMG;

                return `
                    <div class="d-flex justify-content-between align-items-center mb-3 border-bottom pb-3">
                        <div class="d-flex align-items-center gap-3">
                            <img src="${safeImg}" width="50" height="50" class="rounded object-fit-cover" onerror="this.src='${ERROR_IMG}'"/>
                            <div>
                                <h6 class="m-0 fw-bold">${item.title}</h6>
                                <small class="text-muted">${variantLabel} x ${item.qty}</small>
                                ${exLabel}
                            </div>
                        </div>
                        <div class="d-flex align-items-center gap-3">
                            <span class="fw-bold">${App.Utils.formatPrice(lineTotal)}</span>
                            <button class="btn-trash" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                        </div>
                    </div>
                `;
            }).join('');

            // CALCULATE FEES & DISCOUNTS
            let fee = 0;
            if(App.State.orderType === 'delivery') {
                const isFree = subtotal >= DELIVERY_THRESHOLD || (App.State.discount && App.State.discount.type === 'free_ship');
                fee = isFree ? 0 : DELIVERY_COST;

                const percent = Math.min((subtotal / DELIVERY_THRESHOLD) * 100, 100);
                document.getElementById('delivery-bar').style.width = `${percent}%`;

                if (isFree) {
                    document.getElementById('delivery-msg-text').innerHTML = `<i class="bi bi-check-circle-fill text-success"></i> Free Delivery Unlocked!`;
                    document.getElementById('delivery-amount-text').innerText = "";
                } else {
                    const diff = DELIVERY_THRESHOLD - subtotal;
                    document.getElementById('delivery-msg-text').innerText = "Add more for FREE delivery!";
                    document.getElementById('delivery-amount-text').innerText = `${App.Utils.formatPrice(diff)} left`;
                }
                document.getElementById('fee-row').style.display = 'flex';
            } else {
                document.getElementById('fee-row').style.display = 'none';
            }

            // PERCENT DISCOUNT
            let discAmount = 0;
            if(App.State.discount && App.State.discount.type === 'percent') {
                 discAmount = subtotal * App.State.discount.val;
                 document.getElementById('discount-row').classList.remove('d-none');
                 document.getElementById('cart-discount-val').innerText = `-${App.Utils.formatPrice(discAmount)}`;
            } else {
                 document.getElementById('discount-row').classList.add('d-none');
            }

            const total = subtotal + fee - discAmount;

            document.getElementById('cart-subtotal').innerText = App.Utils.formatPrice(subtotal);
            document.getElementById('cart-delivery-fee').innerText = fee === 0 ? "FREE" : App.Utils.formatPrice(fee);
            document.getElementById('cart-total-display').innerText = App.Utils.formatPrice(total);

            App.UI.updateBadge();
        },

        finalizeOrder: () => {
            const nameIn = document.getElementById('cust-name');
            const phoneIn = document.getElementById('cust-phone');
            const addrIn = document.getElementById('cust-address');
            const captIn = document.getElementById('captcha-input');

            [nameIn, phoneIn, addrIn, captIn].forEach(el => el.classList.remove('is-invalid'));

            let isValid = true;
            if(!nameIn.value) { nameIn.classList.add('is-invalid'); isValid = false; }
            if(!phoneIn.value) { phoneIn.classList.add('is-invalid'); isValid = false; }

            if(App.State.orderType === 'delivery' && !addrIn.value) { addrIn.classList.add('is-invalid'); isValid = false; }

            if(parseInt(captIn.value) !== App.State.captchaAnswer) {
                captIn.classList.add('is-invalid');
                App.UI.toast('Math incorrect. Try again.', 'danger');
                isValid = false;
            }

            if(!isValid) {
                App.UI.toast('Please check highlighted fields.', 'warning');
                return;
            }

            const pay = document.getElementById('payment-method').value;
            const notes = document.getElementById('cust-notes').value;
            const order = { 
                id: App.Utils.generateId(),
                date: new Date().toLocaleDateString(), 
                total: document.getElementById('cart-total-display').innerText,
                timestamp: Date.now()
            };

            App.State.history.unshift(order);
            localStorage.setItem('se_hist', JSON.stringify(App.State.history));

            let text = `*ORDER #${order.id.toUpperCase()}* %0A`;
            text += `TYPE: ${App.State.orderType === 'delivery' ? '🛵 DELIVERY' : '🛍️ TAKEAWAY'} %0A`;
            text += `👤 ${nameIn.value} %0A`;
            text += `📞 ${phoneIn.value} %0A`;
            if(App.State.orderType === 'delivery') text += `📍 ${addrIn.value} %0A`;
            text += `💳 ${pay} %0A`;
            if(notes) text += `📝 ${notes} %0A`;
            if(App.State.activeCoupon) text += `🎟️ CODE: ${App.State.activeCoupon} %0A`;
            text += `--------------------------------%0A`;

            App.State.cart.forEach(i => {
                const varLabel = i.multiplier > 1 ? `(${i.multiplier === 1.2 ? 'Box' : 'Party'})` : '';
                const exLabel = (i.extras && i.extras.length) ? `[+${i.extras.map(e=>e.name).join(',')}]` : '';
                text += `• *${i.qty}x* ${i.title} ${varLabel} ${exLabel} %0A`;
            });

            text += `--------------------------------%0A`;
            text += `*TOTAL: ${order.total}*`;

            window.open(`https://wa.me/212666000000?text=${text}`);

            App.Cart.clearAll();
        },

        changeCurrency: (c) => {
            App.State.currency = c;
            localStorage.setItem('se_curr', c);
            App.Catalog.resetGrid();
            App.Cart.render();
        }
    },

    // --- WISHLIST MODULE ---
    Wishlist: {
        toggle: (id) => {
            const idx = App.State.wishlist.findIndex(i => String(i.id) === String(id));
            if(idx > -1) {
                App.State.wishlist.splice(idx, 1);
                App.UI.toast('Removed from favorites', 'light');
            } else {
                const p = App.State.catalog.find(i => String(i.id) === String(id));
                if(p) {
                    App.State.wishlist.push(p);
                    App.UI.toast('Added to favorites', 'success');
                }
            }
            localStorage.setItem('se_wish', JSON.stringify(App.State.wishlist));
            if(window.location.hash === '#wishlist') App.Wishlist.render();
            App.Catalog.resetGrid();
        },

        clearAll: () => {
            if(App.State.wishlist.length === 0) return;
            App.UI.confirm('Clear Favorites', 'Remove all items?', () => {
                App.State.wishlist = [];
                localStorage.setItem('se_wish', JSON.stringify([]));
                App.Wishlist.render();
            });
        },

        render: () => {
            const root = document.getElementById('wishlist-grid-root');
            root.innerHTML = '';
            if(App.State.wishlist.length === 0) {
                 root.innerHTML = `
                    <div class="text-center py-5 w-100">
                        <i class="bi bi-heart text-muted" style="font-size: 3rem;"></i>
                        <h5 class="mt-3 text-muted">No favorites yet</h5>
                    </div>
                `;
                return;
            }
            App.State.wishlist.forEach(item => {
                App.Catalog.createCard(item) ? root.appendChild(App.Catalog.createCard(item)) : null;
            });
        }
    },

    // --- PROFILE MODULE ---
    Profile: {
        renderHistory: () => {
            const tbody = document.getElementById('order-history-body');
            if(!tbody) return;

            if (App.State.history.length === 0) {
                tbody.innerHTML = `<tr><td colspan="3" class="text-center text-muted">No orders yet.</td></tr>`;
                return;
            }

            tbody.innerHTML = App.State.history.map(o => {
                const diff = (Date.now() - (o.timestamp || Date.now())) / 60000;
                let status = '<span class="badge bg-secondary">Pending</span>';

                if (diff > 2 && diff <= 15) status = '<span class="badge bg-warning text-dark">Preparing</span>';
                else if (diff > 15 && diff <= 45) status = '<span class="badge bg-info text-white">Delivering</span>';
                else if (diff > 45) status = '<span class="badge bg-success">Completed</span>';

                return `
                    <tr>
                        <td>
                            <div class="fw-bold">${o.date}</div>
                            <small class="text-muted">#${o.id ? o.id.toUpperCase() : '---'}</small>
                        </td>
                        <td class="fw-bold">${o.total}</td>
                        <td>${status}</td>
                    </tr>
                `;
            }).join('');
        }
    },

    init: () => {
        AOS.init();

        try {
            let c = JSON.parse(localStorage.getItem('se_cart')) || [];
            let w = JSON.parse(localStorage.getItem('se_wish')) || [];
            let h = JSON.parse(localStorage.getItem('se_hist')) || [];
            let curr = localStorage.getItem('se_curr') || 'DH';

            c = c.filter(i => i && typeof i.id !== 'undefined');
            w = w.filter(i => i && typeof i.id !== 'undefined');

            App.State.cart = c;
            App.State.wishlist = w;
            App.State.history = h;
            App.State.currency = curr;
        } catch(e) {
            console.warn("Storage reset");
            App.State.cart = []; App.State.wishlist = [];
        }

        API.fetch();
        App.Catalog.init();
        App.UI.updateBadge();
        App.Utils.checkStatus();
        App.Utils.startCountdown();

        // Safety Valve
        setTimeout(() => {
            const overlay = document.getElementById('maint-overlay');
            if(overlay && overlay.style.display !== 'none') {
                overlay.style.display = 'none';
            }
        }, 4000);

        const route = () => {
            const hash = window.location.hash || '#home';
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const target = document.querySelector(hash + '-module');
            if(target) target.classList.add('active');

            if(hash === '#cart') App.Cart.render();
            if(hash === '#wishlist') App.Wishlist.render();
            if(hash === '#profile') App.Profile.renderHistory();
            window.scrollTo(0,0);
        };
        window.addEventListener('hashchange', route);
        route();

        window.addEventListener('scroll', () => {
            const btn = document.getElementById('scrollTopBtn');
            if(window.scrollY > 300) btn.classList.add('visible');
            else btn.classList.remove('visible');
        });

        if(document.getElementById('delivery-time')) flatpickr("#delivery-time", { enableTime: true });
    }
};

const API = {
    fetch: () => {
        const s = document.createElement('script');
        s.src = 'https://eventsushi.blogspot.com/feeds/posts/default?alt=json-in-script&callback=API.parse&max-results=500';
        s.onerror = () => API.loadFallback();
        document.body.appendChild(s);
    },

    parse: (json) => {
        try {
            if(!json || !json.feed || !json.feed.entry || json.feed.entry.length === 0) {
                API.loadFallback();
                return;
            }

            const cats = new Set(['All']);
            App.State.catalog = json.feed.entry.map(e => {
                const tags = e.category ? e.category.map(c => c.term) : [];
                const meta = App.Catalog.processTags(tags);
                if(meta.cat) cats.add(meta.cat);
                return {
                    id: e.id.$t,
                    title: e.title.$t,
                    img: e.media$thumbnail ? e.media$thumbnail.url.replace(/\/s[0-9]+.*?\//, '/w600-h600-c/') : PLACEHOLDER_IMG,
                    price: meta.price,
                    stock: meta.stock,
                    cat: meta.cat,
                    altImg: meta.altImg,
                    sku: meta.sku,
                    oldPrice: meta.oldPrice,
                    isHot: meta.isHot
                };
            });
            API.finalize(cats);
        } catch(e) {
            console.error("Parse Error:", e);
            API.loadFallback();
        }
    },

    loadFallback: () => {
        console.log('Using Resilient Demo Data');
        const dummy = [
            {id:'1', title:'Dragon Roll', price: 80, stock:10, cat:'Sushi', img:'https://placehold.co/600x400/ce1212/ffffff?text=Dragon+Roll', sku:'F1', oldPrice: 100},
            {id:'2', title:'Miso Soup', price: 25, stock:50, cat:'Soup', img:'https://placehold.co/600x400/37373f/ffffff?text=Miso+Soup', sku:'F2'},
            {id:'3', title:'Spicy Tuna', price: 90, stock:2, cat:'Sushi', img:'https://placehold.co/600x400/ffc107/333333?text=Spicy+Tuna', sku:'F3', oldPrice: 120},
            {id:'4', title:'Sold Out Item', price: 100, stock:0, cat:'Sushi', img:'https://placehold.co/600x400/cccccc/000000?text=Sold+Out', sku:'F4'}
        ];
        App.State.catalog = dummy;
        API.finalize(new Set(['All', 'Sushi', 'Soup']));
    },

    finalize: (cats) => {
        const fContainer = document.getElementById('category-filters');
        fContainer.innerHTML = Array.from(cats).map(c => 
            `<button class="filter-chip ${c==='All'?'active':''}" onclick="App.Catalog.filter('${c}')">${App.Utils.getEmoji(c)} ${c} <span class="badge bg-secondary ms-1" style="font-size:0.7em">${App.State.catalog.filter(i=>i.cat===c).length}</span></button>`
        ).join('');

        document.getElementById('filter-skeleton').classList.add('d-none');
        App.State.filteredCatalog = App.State.catalog;
        App.Catalog.renderBatch();
        document.getElementById('maint-overlay').style.display = 'none';
    }
};

document.addEventListener('DOMContentLoaded', App.init);
//
